From a98b5e7708de548e0e448c9e6cd227146d4b2dee Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 11:00:26 +0100
Subject: [PATCH] applets/taskmanager: focus tasks when the widget's shortcut
 is pressed

The task manager has no popup, so its "Activate widget" shortcut only
toggled an unused expanded state. Give the panel keyboard focus on the
active or first task instead, and release it when pressed again.

BUG: 499774
---
 applets/taskmanager/qml/main.qml | 14 ++++++++++++++
 1 file changed, 14 insertions(+)

diff --git a/applets/taskmanager/qml/main.qml b/applets/taskmanager/qml/main.qml
index d0a62d21bc..2aaab48058 100644
--- a/applets/taskmanager/qml/main.qml
+++ b/applets/taskmanager/qml/main.qml
@@ -302,6 +302,20 @@ PlasmoidItem {
             // erty updates.
             iconGeometryTimer.start();
         }
+
+        function onActivated(): void {
+            if (Plasmoid.containment.status === PlasmaCore.Types.AcceptingInputStatus && taskList.children.some(item => item.activeFocus)) {
+                Plasmoid.containment.status = PlasmaCore.Types.PassiveStatus;
+                return;
+            }
+            const activeRow = tasksModel.activeTask.parent.valid ? tasksModel.activeTask.parent.row : tasksModel.activeTask.row;
+            const task = (taskRepeater.itemAt(activeRow) ?? taskRepeater.itemAt(0)) as Task;
+            if (!task) {
+                return;
+            }
+            Plasmoid.containment.status = PlasmaCore.Types.AcceptingInputStatus;
+            task.forceActiveFocus(Qt.ShortcutFocusReason);
+        }
     }

     Connections {
